         emitter.renderFull();
         ProtocolFrame resync = sink.frame();
         assertTrue(containsText(resync, "wide"), "resync re-emits the selected child");
         assertFalse(containsText(resync, "compact"), "the dowgraded tree no longer carries the other candidate");
