                             guest.set_property(node, prop, value_type_for(prop), v)?;
                             out += 1;
                         }
                         if let Some(s) = self.snapshot_mut(node) {
                             match new_value {
                                 Some(v) => {
                                     s.properties.insert(prop, v);
                                 }
                                 None => {
                                     s.properties.remove(&prop);
                                 }
                             }
                         }
                     }
                 }
