         let lists_changed = match &prev {
             Some(p) => {
                 p.list_properties.len() != lists.len()
                     || p.list_properties
                         .iter()
                         .any(|(prop, (old, _))| lists.get(prop) != Some(old))
             }
             None => !lists.is_empty(),
