                     for (prop, path) in token_refs {
                         let (arena, changed) = match p.token_refs.get(prop) {
                             Some((old_path, old_offset)) if old_path == path => (*old_offset, false),
                             _ => {
                                 let offset = guest
                                     .alloc_str(path)
                                     .map_err(|_| pathland_core::RingError::Full)?;
