                     string_emit = Some(m);
                 }
                 if lists_changed {
                     let mut m = BTreeMap::new();
                     for (prop, values) in lists {
                         let (arena, changed) = match p.list_properties.get(prop) {
                             Some((old_values, old_offset)) if old_values == values => {
                                 (*old_offset, false)
                             }
                             _ => {
