 }

 impl SignalValueKind for String {
     fn into_signal_value(self) -> SignalValue {
         SignalValue::Str(self)
     }
     fn from_signal_value(value: &SignalValue) -> Option<Self> {
         match value {
             SignalValue::Str(v) => Some(v.clone()),
             _ => None,
